all_entries = raw_vocabulary + more_words
seen = set()
dataset = []

for item in all_entries:
    word_en, word_hi, phonetic, pos, ex_en, ex_hi, cat = item
    key = word_en.strip().lower()
    if key not in seen:
        seen.add(key)
        dataset.append({
            "word_en": word_en.strip(),
            "word_hi": word_hi.strip(),
            "phonetic": phonetic.strip(),
            "part_of_speech": pos.strip(),
            "example_en": ex_en.strip(),
            "example_hi": ex_hi.strip(),
            "category": cat.strip()
        })

print(f"Total unique curated student vocabulary entries: {len(dataset)}")

# 1. Create and seed SQLite database
if os.path.exists(OUTPUT_DB):
    os.remove(OUTPUT_DB)

conn = sqlite3.connect(OUTPUT_DB)
cursor = conn.cursor()

# Enable WAL mode
cursor.execute("PRAGMA journal_mode = WAL;")

# Create schema exactly as specified
cursor.execute("""
CREATE TABLE IF NOT EXISTS dictionary (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    word_en TEXT NOT NULL,
    word_hi TEXT NOT NULL,
    phonetic TEXT,
    part_of_speech TEXT,
    example_en TEXT,
    example_hi TEXT,
    category TEXT
);
""")

cursor.execute("CREATE INDEX IF NOT EXISTS idx_word_en ON dictionary(word_en);")
cursor.execute("CREATE INDEX IF NOT EXISTS idx_word_hi ON dictionary(word_hi);")

# Insert dataset
for entry in dataset:
    cursor.execute("""
    INSERT INTO dictionary (word_en, word_hi, phonetic, part_of_speech, example_en, example_hi, category)
    VALUES (?, ?, ?, ?, ?, ?, ?)
    """, (
        entry["word_en"],
        entry["word_hi"],
        entry["phonetic"],
        entry["part_of_speech"],
        entry["example_en"],
        entry["example_hi"],
        entry["category"]
    ))

conn.commit()

# Verify count and indexes
cursor.execute("SELECT COUNT(*) FROM dictionary;")
count = cursor.fetchone()[0]
print(f"[SUCCESS] SQLite Database created at: {OUTPUT_DB}")
print(f"[SUCCESS] Total rows inserted: {count}")

cursor.execute("PRAGMA index_list('dictionary');")
indexes = cursor.fetchall()
print(f"[SUCCESS] Indexes verified: {[idx[1] for idx in indexes]}")

conn.close()

# 2. Generate TypeScript Dataset module for offline Web fallback
ts_content = f"""// ─── Student Dictionary Master Dataset (Classes 1-10) ─────────────────────────
// Generated automatically from scripts/generate_dictionary_db.py

export interface StudentDictionaryEntry {{
  id: number;
  word_en: string;
  word_hi: string;
  phonetic: string;
  part_of_speech: string;
  example_en: string;
  example_hi: string;
  category: 'daily' | 'academic_science' | 'academic_math' | 'exam_vocab' | 'phrases' | string;
}}

export const studentDictionaryEntries: StudentDictionaryEntry[] = {json.dumps([dict(id=i+1, **e) for i, e in enumerate(dataset)], ensure_ascii=False, indent=2)};
"""

with open(OUTPUT_TS, "w", encoding="utf-8") as f:
    f.write(ts_content)

OUTPUT_JSON = os.path.join(ASSETS_DIR, "student_dictionary.json")
with open(OUTPUT_JSON, "w", encoding="utf-8") as f:
    json.dump([dict(id=i+1, **e) for i, e in enumerate(dataset)], f, ensure_ascii=False, indent=2)

print(f"[SUCCESS] JSON Dataset written to: {OUTPUT_JSON}")
print(f"[SUCCESS] TypeScript Dataset written to: {OUTPUT_TS}")
